import base64
import zlib


def gmd_to_objects(raw_data):
    # Returns list of Objects from left to right, bottom to top
    raw_k4_data = raw_data.split("</s><k>k4</k><s>")[1].split("==")[0]
    # Replaces URL safe chars and adds padding
    safe_str = raw_k4_data.replace('-', '+').replace('_', '/')
    padding = len(safe_str) % 4
    if padding:
        safe_str += '=' * (4 - padding)

    compressed_data = base64.b64decode(safe_str)

    # Decompress ('eJ' indicates Zlib)
    # 15+32 tells zlib to accept zlib or gzip headers
    plain_text_level = zlib.decompress(compressed_data, 15 + 32).decode('utf-8')

    # Parse into Object List
    # The string structure is: LevelSettings;Object1;Object2;...
    sections = plain_text_level.split(';')


    level_settings = sections[0]  # The first part is general level info (bg, speed, music)
    object_strings = sections[1:]  # The rest are actual game objects
    # print(object_strings)

    parsed_objects = []

    # Mapping commonly used keys to human names
    key_map = {
        '1': 'id', '2': 'x', '3': 'y',
        '4': 'flip_h', '5': 'flip_v',
        '6': 'rotation', '21': 'color_id',
        '32': 'scale', '57': 'groups'
    }

    for obj_str in object_strings:
        if not obj_str: continue  # Skip empty strings at the end

        # Split "key,value,key,value"
        pairs = obj_str.split(',')
        obj_dict = {}

        for i in range(0, len(pairs) - 1, 2):
            key = pairs[i]
            val = pairs[i + 1]
            # Use mapped name if available, otherwise use key ID
            clean_key = key_map.get(key, f"k_{key}")
            obj_dict[clean_key] = val

        parsed_objects.append(obj_dict)

    # Output Results
    print(f"Level Settings String: {level_settings[:50]}...")  # Preview
    print(f"Total Objects Found: {len(parsed_objects)}")
    print("-" * 30)
    print("First 3 Objects (Code Representation):")
    # for idx, obj in enumerate(parsed_objects[:30]):
    for idx, obj in enumerate(parsed_objects):
        print(f"Obj {idx}: {obj}")



